using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;
[InitializeOnLoad]public static class CityMobileAndroidSettings{
static CityMobileAndroidSettings(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityMobileAndroidSettings.request"))return;File.Delete("CityMobileAndroidSettings.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/MobileOptimization/AndroidSettings.txt",e.ToString());Debug.LogException(e);}}
static void Run(){var sc=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var rs=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).ToArray();var textures=rs.SelectMany(r=>r.sharedMaterials).Where(m=>m).Distinct().SelectMany(m=>m.GetTexturePropertyNames().Select(n=>m.GetTexture(n))).OfType<Texture2D>().Distinct().ToArray();int streaming=0;var log=new StringBuilder();foreach(var t in textures){string path=AssetDatabase.GetAssetPath(t);var imp=AssetImporter.GetAtPath(path) as TextureImporter;if(imp==null||!imp.mipmapEnabled||imp.streamingMipmaps||imp.textureShape!=TextureImporterShape.Texture2D||path.Contains("TextMesh"))continue;CityMobileOptimizationBuild.Backup(path+".meta");imp.streamingMipmaps=true;imp.streamingMipmapsPriority=path.Contains("Hospital")||path.Contains("Signs")||path.Contains("Detail Atlas")?1:0;imp.SaveAndReimport();streaming++;log.AppendLine("STREAMING "+path+" resolution and compression unchanged");}
CityMobileOptimizationBuild.Backup("ProjectSettings/QualitySettings.asset");CityMobileOptimizationBuild.Backup("ProjectSettings/ProjectSettings.asset");var quality=new SerializedObject(Unsupported.GetSerializedAssetInterfaceSingleton("QualitySettings"));var levels=quality.FindProperty("m_QualitySettings");for(int i=0;i<levels.arraySize;i++){var item=levels.GetArrayElementAtIndex(i);if(!item.FindPropertyRelative("name").stringValue.StartsWith("Mobile"))continue;item.FindPropertyRelative("streamingMipmapsActive").boolValue=true;item.FindPropertyRelative("streamingMipmapsMemoryBudget").floatValue=512;item.FindPropertyRelative("globalTextureMipmapLimit").intValue=0;item.FindPropertyRelative("maximumLODLevel").intValue=0;item.FindPropertyRelative("lodBias").floatValue=1;var excluded=item.FindPropertyRelative("excludedTargetPlatforms");for(int j=excluded.arraySize-1;j>=0;j--)if(excluded.GetArrayElementAtIndex(j).stringValue=="Android")excluded.DeleteArrayElementAtIndex(j);}quality.ApplyModifiedPropertiesWithoutUndo();
PlayerSettings.Android.optimizedFramePacing=true;var apis=PlayerSettings.GetGraphicsAPIs(BuildTarget.Android);if(!apis.Contains(GraphicsDeviceType.OpenGLES3)){PlayerSettings.SetUseDefaultGraphicsAPIs(BuildTarget.Android,false);PlayerSettings.SetGraphicsAPIs(BuildTarget.Android,apis.Concat(new[]{GraphicsDeviceType.OpenGLES3}).ToArray());}
var host=sc.GetRootGameObjects().FirstOrDefault(g=>g.name=="Android Environment Performance");if(!host){host=new GameObject("Android Environment Performance");SceneManager.MoveGameObjectToScene(host,sc);host.AddComponent<CityAndroidFramePacing>();}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);log.AppendLine("SUCCESS streaming textures enabled="+streaming+"; existing dimensions/compression and mobile high renderer appearance preserved. Streaming budget512MB mip limit0, Mobile Low restored as Android option and near LOD enabled. Android optimized frame pacing enabled, target60 (not guaranteed), existing graphics API plus GLES3 fallback. Static mesh batching unchanged (disabled on Android). No build/deploy performed; no Android device connected.");File.WriteAllText("FinalEnvironmentRoadReview/MobileOptimization/AndroidSettings.txt",log.ToString());}}
